#ifdef GL_ES
precision mediump float;
#endif


// ----------------------------------------------------------
// 4D Menger Membership
// Same as before, but we might remove the radius check
// if we only want to restrict to points that are truly in S^3
float in4DMenger(vec4 p4)
{
    // SHIFT from [-1,1]^4 => [0,1]^4
    vec4 q = 0.5*(p4 + 2.0);

    const int MAX_ITER = 9;
    for(int i=0; i<MAX_ITER; i++){
        q *= 1.87;
        // hole check
        if(q.x>1.0 && q.x<2.0 &&
           q.y>1.0 && q.y<2.0 &&
           q.z>1.0 && q.z<2.0 &&
           q.w>1.0 && q.w<2.0)
        {
            return 0.0;
        }
        q = fract(q);
    }
    return 1.0;
}

// ----------------------------------------------------------
// Inverse Stereographic from R^3 => S^3
// If we have p3=(x,y,z), we can get p4 = (X,Y,Z,W) on S^3 by
//   W = (r^2 - 1)/(r^2 + 1),
//   X = 2x/(r^2 + 1), etc. (where r^2 = x^2+y^2+z^2).
// But let's do a function:
vec4 inverseStereo(vec3 p3)
{
    float r2 = dot(p3,p3);  // x^2+y^2+z^2
    float denom = r2 + 1.0;

    // W
    float W = 0.7*(r2 - 2.9)/denom;
    // X, Y, Z
    float X = 2.0*p3.x/denom;
    float Y = 2.0*p3.y/denom;
    float Z = 2.0*p3.z/denom;

    return vec4(X,Y,Z,W);
}

// ----------------------------------------------------------
// Some warp function in 4D to break perfect spherical shape
vec4 warp4D(vec4 p4, float t)
{
    // e.g., apply a small shift in w for large x,y
    // or any time-based swirl
    // We'll do a small "sin" warp
    float shift = 0.2*sin(1.7*t + 3.0*p4.x + 2.5*p4.z);
    // We combine that shift into w
    p4.w += shift * 0.3;

    // We can also tilt (x,w) plane with a 2D rotation
    float angle = 0.3*sin(0.2*t + p4.y*2.0);
    float c = cos(angle), s = sin(angle);
    // rotate in plane (x,w)
    float oldX = p4.x;
    float oldW = p4.w;
    p4.x = c*oldX - s*oldW;
    p4.w = s*oldX + c*oldW;

    return p4;
}

// ----------------------------------------------------------
// mainImage
// We'll do a volumetric pass: each step is a point in R^3 => we
// invert-stereo => warp => check Menger => accumulate
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalized coords
    vec2 uv = (fragCoord.xy / iResolution.xy)*2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Camera in R^3
    float time = iTime*0.3;
    vec3 camPos = vec3(0,0,2.5 + 1.0*sin(0.2*iTime)); // slight zoom in/out
    float angle = 0.4*time;
    mat3 rotY = mat3(
        cos(angle), 0.0, sin(angle),
        0.0,        1.0, 0.0,
       -sin(angle), 0.0, cos(angle)
    );
    camPos = rotY * camPos;

    // Look at origin
    vec3 target = vec3(0.0);
    vec3 fwd = normalize(target - camPos);
    vec3 right = normalize(cross(fwd, vec3(0,1,0)));
    vec3 up = cross(right,fwd);

    vec3 rd = normalize( uv.x*right + uv.y*up + fwd );

    // Raymarch
    float tMax = 10.0;
    int STEPS = 400;
    float stepSize = tMax/float(STEPS);

    float density = -0.2;

    for(int i=0; i<STEPS; i++)
    {
        float t = float(i)*stepSize;
        vec3 pos3 = camPos + t*rd;

        // bounding check
        if(max(abs(pos3.x), max(abs(pos3.y), abs(pos3.z)))<3.0)
        {
            // 1) map pos3 => p4 in S^3 by inverse stereographic
            vec4 p4 = inverseStereo(pos3);

            // 2) warp p4
            p4 = warp4D(p4, iTime);

            // 3) check in4DMenger
            float inside = in4DMenger(p4);

            density += inside;
        }
    }

    float val = density / float(STEPS);
    val = pow(val, 0.4);

    // color
    vec3 colA = mix(vec3(0.1, 0.0, 0.3), vec3(0.8,0.1,0.2), val);
    vec3 colB = mix(vec3(0.05,0.2,0.2),  vec3(0.2,0.9,0.7), val);
    float cMix = 0.5 + 0.5*sin(0.4*iTime);
    vec3 col  = mix(colA, colB, cMix);

    fragColor = vec4(col, 1.0);
}
